BEGIN;
UPDATE LiteralTranslation SET literal_translation='그리고 이것들이 아브라함의 아들 이삭의 족보이니라. 아브라함이 이삭을 낳았더라.' WHERE book_id=1 AND chapter=25 AND verse=19;
UPDATE LiteralTranslation SET literal_translation='그리고 너는 아론에게 속한 그 위임식의 숫양의 가슴을 취하여 여호와 앞에 그것을 흔들어 요제로 삼을지니, 그것이 너의 몫이 될 것이라.' WHERE book_id=2 AND chapter=29 AND verse=26;
UPDATE LiteralTranslation SET literal_translation='그리고 슬로브핫, 헤벨의 아들 길르앗의 아들 마길의 아들 므낫세의 아들에게는 아들이 없었고 딸들뿐이었으니, 그의 딸들의 이름은 말라와 노아와 호글라와 밀가와 디르사이다.' WHERE book_id=6 AND chapter=17 AND verse=3;
UPDATE LiteralTranslation SET literal_translation='네가 거기서부터 더 나아가 다볼의 상수리나무에 이르면, 거기서 벧엘의 하나님께 올라가는 세 사람이 너를 만날 것인데, 하나는 염소 새끼 셋을 메고 있고, 하나는 떡 세 덩이를 메고 있고, 하나는 포도주 한 가죽부대를 메고 있는 자라.' WHERE book_id=9 AND chapter=10 AND verse=3;
UPDATE LiteralTranslation SET literal_translation='그리고 사울은 기브아 끝에 있는 미그론에 있는 석류나무 아래에 앉아 있었고, 그와 함께한 백성은 육백 명 가량이었다.' WHERE book_id=9 AND chapter=14 AND verse=2;
UPDATE LiteralTranslation SET literal_translation='왜냐하면 당신의 종인 내가 아람의 그술에 거할 때에 서원을 서원하였기 때문입니다. 말하기를, "만약 여호와께서 나를 예루살렘으로 확실히 돌아오게 하시면, 내가 헤브론에서 여호와를 섬기리이다."' WHERE book_id=10 AND chapter=15 AND verse=8;
UPDATE LiteralTranslation SET literal_translation='이스라엘 왕이 여호사밧에게 말하였다. "여호와께 여쭈어 볼 한 사람, 이믈라의 아들 미가야가 아직 남아 있으나, 그가 나에 대하여 선한 것은 예언하지 않고 오직 악한 것만을 예언하기로 내가 그를 미워하나이다." 여호사밧이 말하였다. "왕은 그렇게 말씀하지 마소서."' WHERE book_id=11 AND chapter=22 AND verse=8;
UPDATE LiteralTranslation SET literal_translation='요람 왕이 아람 왕 하사엘과 싸울 때에 아람 사람들이 라마에서 그를 친 상처들을 치료하기 위하여 이스르엘로 돌아왔고, 유다 왕 여호람의 아들 아하시야가 아합의 아들 요람을 보러 이스르엘로 내려갔으니 이는 그가 병들었기 때문이었다.' WHERE book_id=12 AND chapter=8 AND verse=29;
UPDATE LiteralTranslation SET literal_translation='그리고 요아스, 여호아하스의 아들이 되돌려받았다. 그리고 그가 성읍들을 하사엘의 아들 하닷벤하닷의 손으로부터 빼앗았는데, 그(하닷벤하닷)는 그의 아버지 여호아하스로부터 전쟁 중에 빼앗았던 것이다. 요아스가 그를 세 번 쳐서 물리쳤고, 이스라엘의 성읍들을 되돌려받았다.' WHERE book_id=12 AND chapter=13 AND verse=25;
UPDATE LiteralTranslation SET literal_translation='그리고 솔로몬의 말들의 반출은 이집트로부터였고, 왕의 상인들은 구에에서 그 무리(무역군)를 정가에 따라 취하였다.' WHERE book_id=14 AND chapter=1 AND verse=16;
UPDATE LiteralTranslation SET literal_translation='그리고 웃시야에게 전쟁을 수행하는 군대가 있었으니, 그들의 조사된 수효대로 서기관 여이엘과 관리 마아세야의 손으로 떼를 지어 군대로 나가는 자들이었다. 그들은 왕의 지휘관들 중 하나인 하나냐의 수하(손)에 있었다.' WHERE book_id=14 AND chapter=26 AND verse=11;
UPDATE LiteralTranslation SET literal_translation='내가 그들을 가시뱌 그 장소에 있는 우두머리 잇도에게 보내도록 명령하였고, 내가 그들의 입에 잇도와 그의 형제 느디님들에게 우리 하나님의 집을 위하여 수종 들 자를 데려오라고 말할 말씀들을 두었다.' WHERE book_id=15 AND chapter=8 AND verse=17;
UPDATE LiteralTranslation SET literal_translation='그리고 하늘들이 당신의 기사를, 여호와여, 찬양할 것이며, 또한 당신의 성실함을 거룩한 자들의 회중 안에서 찬양할 것입니다.' WHERE book_id=19 AND chapter=89 AND verse=5;
UPDATE LiteralTranslation SET literal_translation='모레셋 사람 미가가 유다 왕 히스기야의 날들에 유다 모든 백성에게 예언하여 말하기를, 만군의 여호와께서 이같이 말씀하시되, 시온은 밭처럼 갈아질 것이며 예루살렘은 무더기들이 될 것이고, 그 집의 산은 수풀의 산당들이 될 것이라 하였느니라.' WHERE book_id=24 AND chapter=26 AND verse=18;
UPDATE LiteralTranslation SET literal_translation='그리고 나의 숙부의 아들 하나멜이 여호와의 말씀대로 시위대 뜰에 있는 내게로 와서 내게 이르기를, "청하노니 아나돗에 있고 베냐민 땅에 있는 나의 밭을 사거라. 왜냐하면 유업의 권리가 네게 있고 무를 권리가 네게 있기 때문이니, 너를 위하여 사라" 하였는데, 내가 이것이 여호와의 말씀인 줄 알았더라.' WHERE book_id=24 AND chapter=32 AND verse=8;
UPDATE LiteralTranslation SET literal_translation='내 손들과 내 발들을 보라, 왜냐하면 바로 나 자신이 그이기 때문이다. 나를 만져보고 보라, 왜냐하면 영은 살과 뼈들을 가지고 있지 않기 때문이다, 너희가 나에게서 보고 있는 것처럼.' WHERE book_id=42 AND chapter=24 AND verse=39;
UPDATE LiteralTranslation SET literal_translation='그리고 회중의 장로들은 그들의 손들을 그 수송아지의 머리 위에 여호와 앞에서 얹을 것이며, 그 수송아지를 여호와 앞에서 잡을 것이다.' WHERE book_id=3 AND chapter=4 AND verse=15;
UPDATE LiteralTranslation SET literal_translation='그리고 그가 여호와의 궤를 그 성읍을 한 번 돌게 하였고, 그들이 진으로 들어와 그 진에서 유숙하였다.' WHERE book_id=6 AND chapter=6 AND verse=11;
UPDATE LiteralTranslation SET literal_translation='사무엘이 기름병을 취하여 그의 머리 위에 붓고, 그에게 입맞추며 말하였다. 여호와께서 네게 기름을 부어 그분의 기업 위에 그분의 백성 이스라엘 위에 영도자로 삼으시지 아니하였느냐?' WHERE book_id=9 AND chapter=10 AND verse=1;
UPDATE LiteralTranslation SET literal_translation='그리고 르호보암이 예루살렘에 이르러 유다의 온 집과 베냐민 지파를 모으니, 선택된 전사 십팔만 명이라, 이스라엘의 집과 싸워 왕국을 솔로몬의 아들 르호보암에게 돌리려 하였더라.' WHERE book_id=11 AND chapter=12 AND verse=21;
UPDATE LiteralTranslation SET literal_translation='그리고 아하시야가 사마리아에 있는 그 다락에 있는 그 격자 난간을 통하여 떨어졌고 병들었다. 그리고 그가 사자들을 보냈고 그들에게 이르기를, 가서 에그론의 신 바알세붑에게 이 병으로부터 내가 살 것인지 물어보라 하였더라.' WHERE book_id=12 AND chapter=1 AND verse=2;
UPDATE LiteralTranslation SET literal_translation='요람 왕이 아람 왕 하사엘과 아람 사람들과 싸울 때에 아람 사람들이 그를 친 상처들을 치료하기 위하여 이스르엘로 돌아왔는데, 예후가 말하기를 “너희의 뜻에 합당하다면, 이 성에서 도망쳐 이스르엘에 가서 알릴 생존자가 한 명도 나가지 못하게 하라”고 하였다.' WHERE book_id=12 AND chapter=9 AND verse=15;
UPDATE LiteralTranslation SET literal_translation='여호와께서 말씀하셨다. "나 또한 유다를 내 얼굴 앞에서 내가 이스라엘을 물리친 것처럼 물리칠 것이며, 내가 선택했던 이 성읍 예루살렘과 내 이름을 그곳에 두겠다고 내가 말했던 그 집을 버릴 것이다."' WHERE book_id=12 AND chapter=23 AND verse=27;
UPDATE LiteralTranslation SET literal_translation='그리고 그들의 형제들은 그들의 마을들 안에 있으면서 때로부터 때까지 이레(일곱 날)를 위하여 그들과 함께 온다.' WHERE book_id=13 AND chapter=9 AND verse=25;
UPDATE LiteralTranslation SET literal_translation='이것은 그들이 아닥사스다 왕에게 보낸 편지의 초본이라. 강 저편의 신복들인 사람들은 이제...' WHERE book_id=15 AND chapter=4 AND verse=11;
UPDATE LiteralTranslation SET literal_translation='그리고 그의 모든 형제들과 모든 그의 자매들과 전에 알던 모든 자들이 그에게 왔고, 그들이 그의 집에서 그와 함께 음식을 먹었으며, 그를 위해 머리를 흔들고(애도하고), 그에게 여호와께서 내리신 모든 악에 대하여 그를 위로하였고, 그에게 각자 ''케시타''(금 한 조각) 하나씩과 금 귀고리 하나씩을 주었다.' WHERE book_id=18 AND chapter=42 AND verse=11;
UPDATE LiteralTranslation SET literal_translation='그것(여호와의 말씀)이 임하였다, 유다 왕 아몬의 아들 요시야의 날들에 그에게, 그의 통치 제십삼 년에.' WHERE book_id=24 AND chapter=1 AND verse=2;
UPDATE LiteralTranslation SET literal_translation='밭들을 은으로 그들이 살 것이며, 책에 기록하고, 인봉하고, 증인들을 베냐민 땅과 예루살렘 사방과 유다 성읍들과 산지 성읍들과 평지 성읍들과 남방 성읍들에서 증언하게 하리니, 이는 내가 그들의 포로 됨을 돌이키기 때문이라, 여호와의 말씀이니라.' WHERE book_id=24 AND chapter=32 AND verse=44;
UPDATE LiteralTranslation SET literal_translation='그리고 그들이 이 모든 말씀들을 들었을 때에 그들이 두려워하며, 각 사람이 자기 이웃을 향해 서로 바룩에게 말하기를 "우리가 이 모든 말씀들을 왕에게 반드시 고하리라" 하였다.' WHERE book_id=24 AND chapter=36 AND verse=16;
UPDATE LiteralTranslation SET literal_translation='그 구덩이는 이스마엘이 게달리야의 손으로 그가 죽인 모든 사람들의 시체를 그곳에 던져 넣은 곳인데, 그것은 아사 왕이 이스라엘 왕 바아사 때문에 만든 것이라, 느다냐의 아들 이스마엘이 그것을 살해된 자들로 채웠다.' WHERE book_id=24 AND chapter=41 AND verse=9;
UPDATE LiteralTranslation SET literal_translation='무엇으로 내가 너에게 증거할까? 무엇으로 내가 너에게 비유할까? 시온의 처녀 딸 예루살렘아, 무엇으로 내가 너에게 비교하여 너를 위로할까? 네 파멸이 바다처럼 크니, 누가 너를 고칠 수 있겠느냐?' WHERE book_id=25 AND chapter=2 AND verse=13;
COMMIT;
